{
  "positionId": "P01",
  "interviews": [
    {
      "categoryId": "P01-C2",
      "itemId": "P01-C2-I1",
      "interviewBlueprint": {
        "questionIntent": "신고 목록 조회 시간의 단축을 쿼리 개선의 효과로 판단한 근거가 실제 측정 결과에 기반하는지 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "포켓마켓 인턴 때 운영 화면의 신고 목록 조회에 3.2초가 걸렸다.",
          "task": "느린 조회의 병목을 개선하고 응답 시간 단축 효과를 확인해야 했다.",
          "action": "실행 계획을 바탕으로 인덱스와 조인을 수정하고 전후 조회 시간을 확인했다.",
          "result": "조회 시간이 0.4초로 줄어든 결과를 쿼리 수정과 연결해 설명한다."
        },
        "expectedEvidence": [
          "조회 시간 단축을 쿼리 수정의 효과로 판단한 구체적인 근거를 설명한다.",
          "개선 전후 조회 시간을 비교한 실제 측정 결과를 제시한다.",
          "실행 계획에서 찾은 병목이 수정으로 어떻게 달라졌는지 설명한다."
        ]
      },
      "question": "포켓마켓에서 인덱스와 조인을 손봐 신고 목록 조회를 3.2초에서 0.4초로 줄이셨던데요. 이 단축이 쿼리를 바꾼 효과라는 점은 어떤 근거로 판단하셨나요?",
      "answerTip": "당시 확인한 사실을 중심으로 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "실제 측정 결과를 근거로 조회 시간 단축을 쿼리 수정의 효과로 판단한 이유를 구체적으로 설명한다.",
            "실행 계획에서 확인한 병목의 변화와 개선 전후 조회 시간의 차이를 연결한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "쿼리 수정 후 조회 시간이 줄었다는 근거는 답하지만 측정 결과나 병목 변화에 대한 설명이 피상적이다."
          ]
        },
        "poor": {
          "criteria": [
            "인덱스나 조인의 일반적인 장점만 설명하고 실제 조회 시간 단축을 판단한 근거는 답하지 못한다."
          ]
        }
      }
    },
    {
      "categoryId": "P01-C2",
      "itemId": "P01-C2-I2",
      "interviewBlueprint": {
        "questionIntent": "스케줄러 중복 실행의 원인에 비추어 배포 체크리스트를 재발 방지 조치로 선택한 이유를 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "포켓마켓에서 배포 다음 날 같은 알림이 두 번 발송되는 문의가 들어왔다.",
          "task": "알림 중복 발송을 복구하고 같은 장애의 재발을 막아야 했다.",
          "action": "로그로 두 서버의 스케줄러 동시 실행을 찾아 잠금을 적용하고 배포 확인 항목을 추가했다.",
          "result": "체크리스트가 같은 장애의 재발 위험을 줄이는 이유를 원인과 연결해 설명한다."
        },
        "expectedEvidence": [
          "스케줄러 항목을 재발 방지 조치로 추가한 이유를 설명한다.",
          "두 서버의 스케줄러 동시 실행과 배포 시 확인할 내용을 연결한다.",
          "잠금 적용을 통한 오류 수정과 체크리스트의 예방 역할을 구분한다."
        ]
      },
      "question": "포켓마켓에서 알림 중복 발송 후 배포 체크리스트에 스케줄러 항목을 넣으셨던데요. 체크리스트가 같은 장애의 재발을 막는 데 도움이 된다고 보신 이유는 무엇이었나요?",
      "answerTip": "당시의 판단을 구체적으로 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "두 서버에서 스케줄러가 동시에 실행된 원인과 배포 확인 내용을 연결해 체크리스트를 추가한 이유를 설명한다.",
            "잠금 적용이 해결한 문제와 체크리스트가 예방하는 재발 위험을 구분해 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "체크리스트를 추가한 이유는 답하지만 확인 누락을 막는다는 일반론에 머물고 장애 원인과의 연결이 약하다."
          ]
        },
        "poor": {
          "criteria": [
            "체크리스트를 추가한 이유를 답하지 못하거나 잠금으로 오류를 수정했다는 사실만 반복한다."
          ]
        }
      }
    }
  ]
}

{
  "positionId": "P02",
  "interviews": [
    {
      "categoryId": "P02-C1",
      "itemId": "P02-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "세탁소 인터뷰에서 파악한 요청을 구현 범위로 구체화하고 개발 담당자와 합의한 판단 근거를 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "세탁소 다섯 곳을 인터뷰해 예약 서비스 요구사항 정의서를 작성한 팀 과제였다.",
          "task": "인터뷰에서 나온 요청을 실제로 구현할 범위로 정리해야 했다.",
          "action": "요청의 목적과 우선순위를 근거로 구현 범위를 정해 개발 담당 팀원과 합의했다.",
          "result": "이번에 구현할 범위를 팀원이 같은 의미로 이해할 수 있게 정리했다."
        },
        "expectedEvidence": [
          "세탁소의 구체적인 요청과 구현 범위를 연결한 판단 근거를 설명한다.",
          "포함하거나 제외한 요청을 실제 사례로 구분한다.",
          "개발 담당 팀원과 합의한 범위가 정의서에 어떻게 남았는지 설명한다."
        ]
      },
      "question": "동네 세탁소 예약 과제에서 개발 담당 팀원과 구현 범위를 조정하셨던데요. 세탁소 다섯 곳의 요청을 어떤 근거로 구현 범위에 반영하셨나요?",
      "answerTip": "당시 실제로 내린 판단을 중심으로 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "구체적인 인터뷰 요청을 들어 구현 범위에 반영한 판단 근거를 설명한다.",
            "포함하거나 제외한 요청과 개발 담당 팀원이 합의한 범위의 문서화 내용이 확인된다."
          ]
        },
        "acceptable": {
          "criteria": [
            "요청을 구현 범위에 반영한 근거는 설명하지만 구체적인 요청이나 범위 구분은 불분명하다."
          ]
        },
        "poor": {
          "criteria": [
            "인터뷰나 문서 작성 사실만 반복하고 구현 범위를 정한 근거를 설명하지 못한다."
          ]
        }
      }
    },
    {
      "categoryId": "P02-C1",
      "itemId": "P02-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "화면설계서의 예외 상황에서 사용자가 이어서 할 행동을 화면 상태에 맞게 설계한 근거를 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "세탁소 예약 서비스 과제에서 예외 상황을 포함한 화면설계서 28장을 작성했다.",
          "task": "예외 상황에서도 사용자가 다음 행동을 알 수 있도록 화면 흐름을 구체화해야 했다.",
          "action": "예외 상황의 화면 상태를 근거로 사용자가 이어서 할 행동을 설계했다.",
          "result": "개발자와 디자이너가 예외 상황 이후의 화면 흐름을 이해할 수 있게 정리했다."
        },
        "expectedEvidence": [
          "구체적인 예외 상황에서 다음 행동을 정한 근거를 설명한다.",
          "해당 화면 상태에서 그 행동으로 이어지는 흐름을 설명한다.",
          "그 행동을 알리는 안내 문구나 버튼을 설계한 내용을 제시한다."
        ]
      },
      "question": "동네 세탁소 예약 과제에서 예외 상황을 포함해 화면설계서 28장을 작성하셨던데요. 예외 상황에서 사용자가 다음에 할 행동은 무엇을 근거로 정하셨나요?",
      "answerTip": "기억나는 실제 사례 하나에 집중해 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "실제로 설계한 예외 상황을 들어 사용자의 다음 행동을 정한 근거를 구체적으로 설명한다.",
            "화면 상태와 다음 행동의 연결이 명확하고 이를 안내한 문구나 버튼이 확인된다."
          ]
        },
        "acceptable": {
          "criteria": [
            "다음 행동을 정한 근거는 답하지만 화면 상태나 안내 방식에 대한 설명은 일반적이다."
          ]
        },
        "poor": {
          "criteria": [
            "예외 상황을 넣었다는 사실만 설명하거나 사용자의 다음 행동을 정한 근거를 답하지 못한다."
          ]
        }
      }
    }
  ]
}

{
  "positionId": "P03",
  "interviews": [
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "평소와 다른 처방을 정상적인 증량으로 단정하지 않고 투약을 보류해 확인할 필요성을 판단하는지 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "푸른결종합병원에서 수술 후 환자의 진통제 용량이 평소의 두 배로 처방되었다.",
          "task": "처방대로 투약하기 전에 용량 차이가 확인이 필요한 사안인지 판단해야 했다.",
          "action": "용량 차이를 환자 상황과 처방 내용에 비추어 검토하고 투약을 보류해 담당의에게 확인했다.",
          "result": "담당의 확인으로 입력 오류를 발견해 잘못된 용량의 투약을 예방했다."
        },
        "expectedEvidence": [
          "정상적인 증량으로 단정할 수 없었던 구체적인 근거를 설명한다.",
          "환자 상황이나 처방 내용에서 실제로 확인한 정보를 제시한다.",
          "불확실한 용량의 투약을 보류하고 담당의에게 확인한 행동을 설명한다."
        ]
      },
      "question": "푸른결종합병원에서 진통제 용량이 평소의 두 배인 처방의 투약을 멈추셨던데요. 처방에 따른 증량보다 담당의 확인이 먼저라고 판단한 근거는 무엇이었나요?",
      "answerTip": "당시 실제로 판단에 사용한 내용을 중심으로 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "실제로 확인한 환자 상황이나 처방 내용을 바탕으로 증량의 적절성을 확신할 수 없었던 근거를 설명한다.",
            "그 불확실성 때문에 투약을 보류하고 담당의에게 확인했다는 연결이 명확하다."
          ]
        },
        "acceptable": {
          "criteria": [
            "평소와 다른 용량이라 확인이 필요했다고 답하지만, 당시 확인한 정보나 판단 근거는 구체적이지 않다."
          ]
        },
        "poor": {
          "criteria": [
            "투약을 보류한 판단 근거를 설명하지 못하거나, 오류였다는 사후 결과만 반복한다."
          ]
        }
      }
    },
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "환자 상태 관찰의 연속성에 필요한 정보를 골라 다음 근무자에게 전달할 필요성을 판단하는지 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "정형외과 병동에서 수술 후 첫 보행 환자의 낙상이 근무 교대 시간대에 집중되었다.",
          "task": "교대 후에도 환자 상태를 이어서 살필 수 있도록 인수인계 정보를 구체화해야 했다.",
          "action": "사고 보고서에서 확인한 문제를 바탕으로 진통제 투여 시각을 인수인계 항목으로 제안했다.",
          "result": "다음 근무자가 환자 상태를 이어서 관찰하는 데 필요한 정보를 전달받는다."
        },
        "expectedEvidence": [
          "진통제 투여 시각을 다음 근무자에게 전달해야 하는 이유를 설명한다.",
          "투여 시각이 투약 후 환자 상태 변화를 해석하는 데 갖는 의미를 설명한다.",
          "사고 보고서에서 확인한 교대 시간대 낙상 양상과 전달 필요성을 연결한다."
        ]
      },
      "question": "푸른결종합병원에서 교대 시간대 낙상에 대응해 인수인계에 진통제 투여 시각을 추가하셨던데요. 다음 근무자에게 이 시각을 꼭 전달해야 한다고 보신 이유는 무엇이었나요?",
      "answerTip": "그때 내린 판단을 구체적으로 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "진통제 투여 시각이 투약 후 환자 상태 변화를 이어서 파악하는 데 필요한 이유를 구체적으로 설명한다.",
            "사고 보고서의 교대 시간대 낙상 양상과 해당 정보를 인수인계할 필요성을 연결한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "환자 상태 관찰이나 낙상 예방을 위해 필요했다고 답하지만, 투여 시각을 전달할 이유는 일반적이다."
          ]
        },
        "poor": {
          "criteria": [
            "진통제 투여 시각을 전달해야 하는 이유를 설명하지 못하거나, 낙상 건수가 감소했다는 결과만 제시한다."
          ]
        }
      }
    }
  ]
}

{
  "positionId": "P04",
  "interviews": [
    {
      "categoryId": "P04-C1",
      "itemId": "P04-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "과제에서 계산한 하중을 축 지름 결정에 연결하고, 선정한 지름의 적절성을 설명하는지 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "기계요소설계 수업에서 주어진 하중으로 축 지름과 베어링을 선정했다.",
          "task": "주어진 하중을 견딜 수 있는 축 지름을 결정해야 했다.",
          "action": "하중으로 발생하는 응력과 재료의 허용 수준을 근거로 지름을 정했다.",
          "result": "선정한 축 지름이 하중 조건에 적절한 이유를 계산서로 설명했다."
        },
